if not doc.institute:
    frappe.throw("Student is missing Institute (Company) information.")

company = frappe.get_doc("Company", doc.institute)

# Map company accounts to GL balance manually
doc.fees = sum(
    entry.debit - entry.credit
    for entry in frappe.get_all(
        "GL Entry",
        filters={
            "party_type": "Student",
            "party": doc.admission_no,
            "account": company.custom_fees_account,
            "company": doc.institute
        },
        fields=["debit", "credit"]
    )
) if company.custom_fees_account else frappe.throw("Account not set in Company for 'Fees'.")

